    14	      id TEXT PRIMARY KEY,
    15	      status TEXT NOT NULL,
    16	      input TEXT NOT NULL,
    17	      steps INTEGER NOT NULL,
    18	      fail_attempts INTEGER NOT NULL,
    19	      attempts INTEGER NOT NULL DEFAULT 0,
    20	      progress_completed INTEGER NOT NULL DEFAULT 0,
    21	      result TEXT,
    22	      error TEXT,
    23	      created_at TEXT NOT NULL,
    24	      updated_at TEXT NOT NULL,
    25	      retry_at INTEGER NOT NULL DEFAULT 0
    26	    );
